async function api(path, data, method='POST') {
  const options={method,headers:{'X-PrintFlow':'local'}};
  if(data instanceof FormData) options.body=data;
  else if(data!==undefined){options.headers['Content-Type']='application/json';options.body=JSON.stringify(data);}
  const response=await fetch(path,options);
  let body;try{body=await response.json();}catch{body={};}
  if(!response.ok){const detail=body.detail||body.error||body.message||"The operation could not be completed.";throw new Error(typeof detail==='string'?detail:JSON.stringify(detail));}
  return body;
}
