function setCameraBadge(label,live){setText('camera-badge',label);$('camera-badge').classList.toggle('muted',!live);}
function cameraUnavailable(message){
  ui.cameraOk=false;const hasFrame=Boolean(ui.cameraLoadedAt)&&ui.cameraRequestId===selectedPrinter()?.id;
  $('camera-image').hidden=!hasFrame;$('camera-empty').hidden=hasFrame;
  setCameraBadge(hasFrame?'LAST FRAME':'RECONNECTING',false);
  setText('camera-status',hasFrame?'Connection interrupted · showing last frame':'Reconnecting to the printer camera…');
  $('camera-status').title=message;$('camera-dot').className='status-dot offline';
  $('camera-empty').querySelector('h3').textContent=selectedPrinter()?.connected?'Reconnecting camera':'Printer offline';
  $('camera-empty').querySelector('p').textContent=selectedPrinter()?.connected?'The printer is connected. Retrying its camera feed automatically.':'Connect the printer to view its camera feed.';
}
async function updateCamera(){
  const p=selectedPrinter();if(!p?.connected||ui.cameraInFlight||document.hidden)return;
  ui.cameraInFlight=true;ui.cameraRequestId=p.id;const requestedId=p.id;
  const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),14000);
  try{
    const response=await fetch('/api/printers/'+encodeURIComponent(p.id)+'/camera.jpg?t='+Date.now(),{cache:'no-store',signal:controller.signal});
    if(!response.ok){let detail='Camera unavailable';try{detail=(await response.json()).detail||detail;}catch{}throw new Error(detail);}
    const blob=await response.blob();if(!blob.type.startsWith('image/'))throw new Error('The printer did not return a camera image');
    const nextUrl=URL.createObjectURL(blob);const probe=new Image();probe.src=nextUrl;
    try{await probe.decode();}catch(error){URL.revokeObjectURL(nextUrl);throw error;}
    if(requestedId!==selectedPrinter()?.id){URL.revokeObjectURL(nextUrl);return;}
    const oldUrl=ui.cameraBlobUrl;ui.cameraBlobUrl=nextUrl;$('camera-image').src=nextUrl;if(oldUrl)URL.revokeObjectURL(oldUrl);
    ui.cameraOk=true;ui.cameraLoadedAt=Date.now();$('camera-image').hidden=false;$('camera-empty').hidden=true;
    setCameraBadge('LIVE · ~1 FPS',true);setText('camera-status','Live · official firmware camera');
    $('camera-status').title='Stock Snapmaker camera · approximately one new frame per second';
    setText('camera-time',new Date().toLocaleTimeString('en-US',{hour12:false}));$('camera-dot').className='status-dot';
  }catch(error){if(requestedId===selectedPrinter()?.id)cameraUnavailable(error.message);}
  finally{clearTimeout(timeout);ui.cameraInFlight=false;}
}
$('retry-camera').addEventListener('click',updateCamera);
