function isJobReady(job){return ['completed','complete','done','success'].includes(job.status)||job.result?.status==='ok';}
function toolpathRole(feature){
  const name=String(feature||'').toLowerCase();
  if(name.includes('support')||name.includes("support"))return 'support';
  if(name.includes('prime')||name.includes('wipe tower')||name.includes("prime"))return 'prime';
  if(name.includes('wall')||name.includes('perimeter'))return 'walls';
  if(name.includes('infill')||name.includes('surface')||name.includes('bridge')||name.includes('solid'))return 'infill';
  return 'other';
}
const toolpathColors={walls:'#8cb7ff',infill:'#8bc6cf',support:'#eeac78',prime:'#b9a0ec',other:'#8292aa'};
async function openToolpaths(job){
  const request=++ui.toolpathRequest;ui.toolpaths=null;ui.toolpathZoom=1;ui.toolpathPan={x:0,y:0};
  const file=ui.state?.files?.find(f=>String(f.id)===String(job.file_id));
  setText('toolpath-title',file?.name||"Print toolpaths");setText('toolpath-note',"Loading toolpaths emitted by the slicer…");
  setText('toolpath-empty',"Reading G-code…");$('toolpath-empty').hidden=false;$('toolpath-layer').disabled=true;setText('toolpath-layer-label','—');setText('toolpath-z','Z — mm');setText('toolpath-segment-count','—');
  if(!$('toolpath-dialog').open)$('toolpath-dialog').showModal();drawToolpaths();
  try{
    const response=await fetch('/api/jobs/'+encodeURIComponent(job.id)+'/toolpaths',{cache:'no-store'});
    let body;try{body=await response.json();}catch{throw new Error("The service did not return readable G-code.");}
    if(!response.ok)throw new Error(body.detail||body.error||"Toolpaths could not be loaded.");
    if(request!==ui.toolpathRequest)return;
    if(!Array.isArray(body.layers)||!body.layers.length)throw new Error("This job has no available extrusion layers.");
    ui.toolpaths=body;
    const range=$('toolpath-layer');range.min='0';range.max=String(body.layers.length-1);range.value='0';range.disabled=false;
    setText('toolpath-note',(body.note||"XY view of actual extrusion moves, separated by layer.")+(body.truncated?" This view contains a reduced toolpath sample.":''));
    $('toolpath-empty').hidden=true;drawToolpaths();
  }catch(error){if(request!==ui.toolpathRequest)return;ui.toolpaths=null;setText('toolpath-note',"Preview unavailable. The original project and G-code remain unchanged.");setText('toolpath-empty',error.message||"The preview could not be loaded.");$('toolpath-empty').hidden=false;drawToolpaths();}
}
function drawToolpaths(){
  const canvas=$('toolpath-canvas'),ctx=canvas.getContext('2d'),dpr=Math.min(devicePixelRatio||1,2),w=canvas.clientWidth||700,h=canvas.clientHeight||420;
  canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);ctx.fillStyle='#111820';ctx.fillRect(0,0,w,h);
  const data=ui.toolpaths;if(!data)return;
  const index=Math.max(0,Math.min(data.layers.length-1,Number($('toolpath-layer').value)||0)),layer=data.layers[index];
  const segments=Array.isArray(layer.segments)?layer.segments.filter(s=>Array.isArray(s)&&s.length>=4&&s.slice(0,4).every(Number.isFinite)):[];
  let bounds=data.bounds;
  if(!bounds||![bounds.min_x,bounds.min_y,bounds.max_x,bounds.max_y].every(Number.isFinite)){
    bounds={min_x:Infinity,min_y:Infinity,max_x:-Infinity,max_y:-Infinity};
    for(const s of segments){bounds.min_x=Math.min(bounds.min_x,s[0],s[2]);bounds.max_x=Math.max(bounds.max_x,s[0],s[2]);bounds.min_y=Math.min(bounds.min_y,s[1],s[3]);bounds.max_y=Math.max(bounds.max_y,s[1],s[3]);}
  }
  setText('toolpath-layer-label',(index+1)+' / '+data.layers.length);setText('toolpath-z','Z '+(Number.isFinite(Number(layer.z))?Number(layer.z).toFixed(2):'—')+' mm');
  setText('toolpath-segment-count',segments.length.toLocaleString("en-US")+" segments in this layer");
  if(!segments.length){ctx.fillStyle='#8a9dbb';ctx.font='12px "Segoe UI",sans-serif';ctx.textAlign='center';ctx.fillText("This layer has no visible segments.",w/2,h/2);return;}
  const dx=Math.max(.1,bounds.max_x-bounds.min_x),dy=Math.max(.1,bounds.max_y-bounds.min_y),scale=Math.min((w-70)/dx,(h-65)/dy)*ui.toolpathZoom;
  const centerX=(bounds.min_x+bounds.max_x)/2,centerY=(bounds.min_y+bounds.max_y)/2;
  const px=x=>w/2+(x-centerX)*scale+ui.toolpathPan.x,py=y=>h/2-(y-centerY)*scale+ui.toolpathPan.y;
  const spacing=scale>12?5:scale>4?10:scale>1.5?25:50;
  const worldMinX=centerX+(-w/2-ui.toolpathPan.x)/scale,worldMaxX=centerX+(w/2-ui.toolpathPan.x)/scale;
  const worldMinY=centerY+(-h/2+ui.toolpathPan.y)/scale,worldMaxY=centerY+(h/2+ui.toolpathPan.y)/scale;
  ctx.lineWidth=1;ctx.strokeStyle='#7186a41f';ctx.beginPath();
  let gridLines=0;for(let x=Math.ceil(worldMinX/spacing)*spacing;x<=worldMaxX&&gridLines<300;x+=spacing,gridLines++){ctx.moveTo(px(x),0);ctx.lineTo(px(x),h);}
  for(let y=Math.ceil(worldMinY/spacing)*spacing;y<=worldMaxY&&gridLines<600;y+=spacing,gridLines++){ctx.moveTo(0,py(y));ctx.lineTo(w,py(y));}ctx.stroke();
  ctx.fillStyle='#7c8ba3';ctx.font='9px Consolas,monospace';ctx.textAlign='left';ctx.fillText('XY · '+spacing+" mm / grid",14,20);
  const byRole={walls:[],infill:[],support:[],prime:[],other:[]};for(const segment of segments)byRole[toolpathRole(segment[4])].push(segment);
  ctx.lineJoin='round';ctx.lineCap='round';ctx.lineWidth=Math.min(3,Math.max(.7,.42*scale));
  for(const role of ['other','infill','support','prime','walls']){ctx.strokeStyle=toolpathColors[role];ctx.beginPath();for(const s of byRole[role]){ctx.moveTo(px(s[0]),py(s[1]));ctx.lineTo(px(s[2]),py(s[3]));}ctx.stroke();}
}
