function markdownInline(target,text){const pattern=/(`[^`]+`|\*\*[^*]+\*\*|\*[^*]+\*|\[[^\]]+\]\([^)]+\))/g;let last=0;const files=ui.state?.files||[],jobs=ui.state?.jobs||[],companions=PrintFlowModelLinks.textModels(text,files,location.origin);for(const job of PrintFlowModelLinks.textJobs(text,jobs,location.origin)){const file=files.find(f=>f.id===job.file_id);if(file&&!companions.some(f=>f.id===file.id))companions.push(file);}for(const match of String(text).matchAll(pattern)){target.append(document.createTextNode(text.slice(last,match.index)));const token=match[0];let node;if(token.startsWith('`'))node=el('code','',token.slice(1,-1));else if(token.startsWith('**'))node=el('strong','',token.slice(2,-2));else if(token.startsWith('*'))node=el('em','',token.slice(1,-1));else{const link=token.match(/^\[([^\]]+)\]\(([^)]+)\)$/),raw=link[2].trim().replace(/^<|>$/g,'');const job=PrintFlowModelLinks.resolveJobLink(raw,jobs,location.origin);let file=PrintFlowModelLinks.resolveModelLink(raw,files,location.origin)||files.find(f=>f.id===job?.file_id);if(!file&&/\.(png|jpe?g|webp)$/i.test(raw)&&/preview/i.test(link[1])&&companions.length===1)file=companions[0];node=el('span','',link[1]);if(file){node=el('a','model-chat-link',link[1]);node.href='#model='+encodeURIComponent(file.id);node.title='Open '+file.name+' in the 3D workspace';node.addEventListener('click',event=>{event.preventDefault();selectFile(file.id);});}else{try{const url=new URL(raw,location.origin);if(['https:','http:'].includes(url.protocol)){node=el('a','',link[1]);node.href=url.href;node.target='_blank';node.rel='noopener noreferrer';}}catch{}}}target.append(node);last=match.index+token.length;}target.append(document.createTextNode(text.slice(last)));}
function renderMarkdown(target,text){target.replaceChildren();target.classList.add('markdown');const lines=String(text||'').slice(0,250000).replace(/\r/g,'').split('\n');let index=0;const cells=line=>line.trim().replace(/^\||\|$/g,'').split('|').map(x=>x.trim());const tableDivider=line=>cells(line||'').length>1&&cells(line).every(x=>/^:?-{3,}:?$/.test(x));
  while(index<lines.length){const line=lines[index];if(!line.trim()){index++;continue;}if(line.trim().startsWith('```')){const code=[];index++;while(index<lines.length&&!lines[index].trim().startsWith('```'))code.push(lines[index++]);if(index<lines.length)index++;const pre=el('pre');pre.append(el('code','',code.join('\n')));target.append(pre);continue;}
    if(index+1<lines.length&&line.includes('|')&&tableDivider(lines[index+1])){const wrap=el('div','chat-table-wrap'),table=el('table'),head=el('thead'),row=el('tr');for(const value of cells(line)){const cell=el('th');markdownInline(cell,value);row.append(cell);}head.append(row);table.append(head);const body=el('tbody');index+=2;while(index<lines.length&&lines[index].includes('|')&&lines[index].trim()){const tr=el('tr');for(const value of cells(lines[index++])){const td=el('td');markdownInline(td,value);tr.append(td);}body.append(tr);}table.append(body);wrap.append(table);target.append(wrap);continue;}
    const heading=line.match(/^(#{1,4})\s+(.+)$/);if(heading){const h=el('h'+Math.min(4,heading[1].length+1));markdownInline(h,heading[2]);target.append(h);index++;continue;}
    if(/^\s*>\s?/.test(line)){const quote=el('blockquote');const values=[];while(index<lines.length&&/^\s*>\s?/.test(lines[index]))values.push(lines[index++].replace(/^\s*>\s?/,''));markdownInline(quote,values.join(' '));target.append(quote);continue;}
    const list=line.match(/^\s*([-*+]|\d+\.)\s+(.+)$/);if(list){const ordered=/\d/.test(list[1]),container=el(ordered?'ol':'ul');while(index<lines.length){const item=lines[index].match(/^\s*([-*+]|\d+\.)\s+(.+)$/);if(!item||/\d/.test(item[1])!==ordered)break;const li=el('li');markdownInline(li,item[2]);container.append(li);index++;}target.append(container);continue;}
    const paragraph=[];while(index<lines.length&&lines[index].trim()){if(paragraph.length&&(/^(?:\s*```|#{1,4}\s|\s*>|\s*[-*+]\s|\s*\d+\.\s)/.test(lines[index])||(index+1<lines.length&&lines[index].includes('|')&&tableDivider(lines[index+1]))))break;paragraph.push(lines[index++]);}const p=el('p');markdownInline(p,paragraph.join(' '));target.append(p);
  }
}
function appendMessage(role,text){const wrap=el('div','chat-message '+role),label=el('div','message-label',role==='user'?'You':role==='error'?'Connection status':'Codex'),body=el('div','message-text',text);if(role==='assistant'&&text)renderMarkdown(body,text);wrap.append(label,body);$('chat-messages').querySelector('.assistant-intro')?.remove();$('chat-messages').append(wrap);$('chat-suggestions').hidden=true;if(role==='user')ui.chatPinned=true;scrollChat();return body;}
