function codexEvent(data){
  if(!data)return;
  const type=data.type||data.method;
  if(type==='progress'){
    if(!ui.state)return;ui.state.codex={...ui.state.codex,progress:data.progress,busy:data.busy};if(data.approval_session)codexApprovalsChanged(data);renderCodex();
  } else if(type==='delta'||type==='item/agentMessage/delta'){
    if(!ui.streamMessage)ui.streamMessage=appendMessage('assistant','');ui.streamMessage.append(document.createTextNode(data.text??data.delta??data.params?.delta??''));scrollChat();
  } else if(type==='message'){
    const text=data.text||'';if(ui.streamMessage){renderMarkdown(ui.streamMessage,text||ui.streamMessage.textContent);ui.streamMessage=null;}else if(text)appendMessage('assistant',text);scrollChat();
  } else if(type==='activity'){scheduleRefresh();}
  else if(type==='done'||type==='turn/completed'){if(ui.streamMessage)renderMarkdown(ui.streamMessage,ui.streamMessage.textContent);ui.streamMessage=null;if(ui.state?.codex){ui.state.codex.busy=false;ui.state.codex.pending_approvals=[];}renderCodex();scheduleRefresh();}
  else if(type==='error'){appendMessage('error',data.text||data.error||"The turn could not be completed.");ui.streamMessage=null;scheduleRefresh();}
  else if(type==='approvals'){codexApprovalsChanged(data);}
  else if(type==='approval'){if(ui.state?.codex){ui.state.codex.pending_approvals=[...(ui.state.codex.pending_approvals||[]).filter(p=>String(p.id)!==String(data.id)),data];}showApproval(data);}
  else if(type==='approval_resolved'){resolveCodexApproval(data.id);if(ui.state?.codex)ui.state.codex.pending_approvals=(ui.state.codex.pending_approvals||[]).filter(p=>String(p.id)!==String(data.id));}
  else if(type==='approval_error'){if(ui.state?.codex)ui.state.codex.approval_error=data.message;renderCodex();}
}
