function renderDesignColorOptions(requested){const printer=designPrinter(),select=$('design-color-mode'),old=requested||select.value;select.replaceChildren();const options=[['single','Single color'],['separate_parts','Separate parts']];const max=Number(printer?.max_colors)||1;if(max>1){if(/ams/i.test(String(printer?.color_system)))options.push(['ams','AMS colors']);else options.push(['multi_tool','Multi-tool colors']);}for(const [value,label] of options){const option=el('option','',label);option.value=value;select.append(option);}if(options.some(o=>o[0]===old))select.value=old;const count=$('design-color-count');count.replaceChildren();for(let i=2;i<=Math.max(2,Math.min(8,max));i++){const option=el('option','',i+' colors');option.value=String(i);count.append(option);}renderDesignPalette();}
function renderDesignPalette(){const roadster=designTemplate()?.id==='roadster_2026';if(roadster){$('design-color-mode').value='multi_tool';$('design-color-count').value='3';} $('design-color-mode').disabled=roadster;$('design-color-count').disabled=roadster;const single=$('design-color-mode').value==='single';$('design-color-count-field').hidden=single;const count=single?1:Number($('design-color-count').value)||2;const target=$('design-colors');for(const [index,input] of [...target.querySelectorAll('input[type=color]')].entries())designState.palette[index]=input.value;target.replaceChildren();const reported=ui.state?.printers?.find(p=>String(p.id)===String(designPrinter()?.id))?.filaments||[];for(let i=0;i<count;i++){const label=el('label','design-color-chip'),color=el('input');color.type='color';const real=reported[i]?.color;const suggested=real?String(real).startsWith('#')?real:'#'+real:null;const value=designState.palette[i]||suggested||['#C8D2E0','#467DCE','#DA9258','#7C91A8'][i%4];color.value=/^#[0-9a-fA-F]{6}$/.test(value)?value:'#C8D2E0';color.setAttribute('aria-label','Design color '+(i+1));color.addEventListener('input',()=>{designState.palette[i]=color.value;});label.append(color,el('span','',roadster?['Trim','Rear lightbar','Body'][i]:'Color '+(i+1)));target.append(label);}}
function collectDesignRequest(){const parameters={};for(const input of document.querySelectorAll('input[data-design-parameter]'))parameters[input.dataset.designParameter]=Number(input.value);return {name:$('design-name').value.trim(),template:$('design-template').value,parameters,printer_id:$('design-printer').value,color_mode:$('design-color-mode').value,colors:[...$('design-colors').querySelectorAll('input[type=color]')].map(input=>input.value),usage:{outdoor:$('design-outdoor').checked,flexible:$('design-flexible').checked,heat:$('design-heat').checked,loaded:$('design-loaded').checked},...(designState.revisionOf?{revision_of:designState.revisionOf}:{})};}
async function submitCadDesign(event){event.preventDefault();if(!$('design-cad-form').reportValidity())return;if(!designState.capabilities?.cad?.available){toast('The local CAD engine is not available.',true);return;}const result=await action(()=>api('/api/designs',collectDesignRequest()),'Design queued. Follow the actual generation status here.',$('create-cad-design'));if(result){await loadDesigns();renderDesignReadiness();}}
async function submitImageDesign(event){event.preventDefault();if(!$('design-image-form').reportValidity())return;if(!designState.capabilities?.image3d?.available){toast('Set up the local image-to-3D worker before generation.',true);return;}const file=$('design-image-file').files[0];if(!file)return;const form=new FormData();form.append('file',file);form.append('name',$('design-image-name').value.trim());form.append('size_mm',$('design-image-size').value);form.append('printer_id',$('design-image-printer').value);form.append('quality',$('design-image-quality').value);form.append('background',$('design-image-background').value);const result=await action(()=>api('/api/designs/image',form),'Image reconstruction queued with the local worker.',$('create-image-design'));if(result){await loadDesigns();renderDesignReadiness();}}
async function loadDesigns(){if(designState.loading)return;designState.loading=true;try{const response=await fetch('/api/designs',{cache:'no-store'});let body;try{body=await response.json();}catch{throw new Error('Design jobs are not available yet.');}if(!response.ok)throw new Error(body.detail||'Design jobs are not available yet.');designState.designs=Array.isArray(body.designs)?body.designs:[];renderDesigns();}catch(error){if(!designState.designs.length){$('design-list').replaceChildren(el('div','design-service-error',error.message||'Design jobs unavailable'));}}finally{designState.loading=false;}}
function designFiles(design){const ids=(design.files||[]).map(file=>typeof file==='object'?file.id:file).filter(id=>id!=null);return ids.map(id=>ui.state?.files?.find(file=>String(file.id)===String(id))||{id,name:'Generated model'});}
async function openDesignLibrary(design){await refresh();const files=designFiles(design);showPage('library');if(files[0]&&ui.state?.files?.some(file=>String(file.id)===String(files[0].id)))selectFile(files[0].id);}
async function editDesign(design){const cap=await loadDesignCapabilities();if(!cap)return;const request=design.request||{};if(!['box','table','spacer','roadster_2026'].includes(request.template)){toast('This image reconstruction has no editable CAD parameters. Use its files in the Library.',true);return;}setDesignMode('cad');$('design-name').value=(design.name||request.name||'Design')+' revision';$('design-template').value=request.template;if((cap.printers||[]).some(p=>String(p.id)===String(request.printer_id)))$('design-printer').value=String(request.printer_id);renderDesignParameters(request.parameters||{});$('design-colors').replaceChildren();designState.palette=Array.isArray(request.colors)?[...request.colors]:[];renderDesignColorOptions(request.color_mode);if(request.colors?.length>1)$('design-color-count').value=String(request.colors.length);renderDesignPalette();for(const key of ['outdoor','flexible','heat','loaded'])$('design-'+key).checked=Boolean(request.usage?.[key]);designState.revisionOf=design.id;setText('design-revision-label','Revision of '+(design.name||'design'));$('design-revision-note').hidden=false;showPage('design');}
function draftDesignWithCodex(design=null){const request=design?.request||(designState.mode==='image'?{name:$('design-image-name').value.trim(),mode:'image',size_mm:Number($('design-image-size').value),reference_image:$('design-image-file').files[0]?.name||null,printer_id:$('design-image-printer').value}:collectDesignRequest()),printer=design?designState.capabilities?.printers?.find(p=>String(p.id)===String(request.printer_id)):designPrinter(designState.mode==='image');const lines=['Help me design a printable part for '+(printer?.name||'the selected printer')+'.','Design context: '+JSON.stringify(request,null,2),'Before proposing changes, ask me about any missing dimensions, fit/tolerance, load, heat exposure, material and assembly requirements. Explain print orientation and bed-size constraints. Do not claim a structural load rating without validation.'];if(design)lines.push('Existing design ID: '+design.id);if(designState.mode==='image')lines.push('I am exploring an image-to-3D reconstruction. Do not assume the local worker is ready or that it can infer engineered joints or semantic color separation.');openChat(true);$('chat-input').value=lines.join('\n\n');$('chat-input').focus();toast('Design context added to the chat draft. Review it and click Send.');}
function renderDesigns(){const designs=[...designState.designs].sort((a,b)=>(Date.parse(b.created_at)||0)-(Date.parse(a.created_at)||0));setText('design-count',designs.length+' '+(designs.length===1?'design':'designs'));const list=$('design-list');list.replaceChildren();if(!designs.length){const empty=el('div','design-empty');empty.append(icon('box'),el('h3','','Designs will appear here'),el('p','','Generate a dimensioned part or submit an image when a local worker is available.'));list.append(empty);return;}for(const design of designs){const card=el('article','design-result'),header=el('div','design-result-heading'),name=el('div');name.append(el('h3','',design.name||'Untitled design'),el('p','',design.stage||jobLabels[design.status]||design.status||'Queued'));header.append(name,el('span','state-tag'+(['error','failed'].includes(design.status)?' error':['complete','completed','ready','done','success'].includes(design.status)?'':' neutral'),jobLabels[design.status]||design.status||'Queued'));card.append(header);if(design.error)card.append(el('p','design-error',typeof design.error==='string'?design.error:JSON.stringify(design.error)));const files=designFiles(design);if(files.length){const thumbnails=el('div','design-thumbnails');for(const file of files.slice(0,4)){const image=el('img');image.src='/api/files/'+encodeURIComponent(file.id)+'/thumbnail?v=4';image.alt='Generated geometry: '+file.name;image.loading='lazy';image.addEventListener('error',()=>{image.hidden=true;});thumbnails.append(image);}card.append(thumbnails);}const actions=el('div','design-result-actions');if(files.length)actions.append(button('Open in Library','primary small',()=>openDesignLibrary(design),'folder'));if(['box','table','spacer','roadster_2026'].includes(design.request?.template))actions.append(button('Edit dimensions','outline small',()=>editDesign(design),'settings'));if(design.engine==='triposr'&&design.status==='ready')actions.append(button('Improve reconstruction','outline small',async()=>{const revision=await action(()=>api('/api/designs/'+design.id+'/refine-image',{quality:'detail',background:'remove'}),'New detail revision queued. The original is preserved.');if(revision)loadDesigns();},'settings'));actions.append(button('Ask Codex','outline small',()=>draftDesignWithCodex(design),'chat'));const downloads=el('div','design-source-links');for(const [kind,label] of (['box','table','spacer','roadster_2026'].includes(design.request?.template)?[['parameters','Parameters'],['step','STEP'],['source','Source']]:[['parameters','Parameters'],['mesh','Color GLB']])){const link=el('a','',label);link.href='/api/designs/'+encodeURIComponent(design.id)+'/source?kind='+kind;link.title='Download '+label.toLowerCase();downloads.append(link);}if(files.length)card.append(downloads);card.append(actions);if(design.advice||design.parts?.length){const details=el('details','design-result-details');details.open=designState.expanded.has(String(design.id));details.addEventListener('toggle',()=>{if(details.open)designState.expanded.add(String(design.id));else designState.expanded.delete(String(design.id));});details.append(el('summary','','Parts & design advice'));if(design.advice){const advice=el('div','message-text');renderMarkdown(advice,typeof design.advice==='string'?design.advice:'**'+(design.advice.material||'Material review')+'**\n\n'+(design.advice.reason||'')+'\n\n'+(design.advice.questions||[]).map(q=>'- '+q).join('\n')+'\n\n'+(design.advice.note||''));details.append(advice);}if(design.parts?.length){const parts=el('ul');for(const part of design.parts)parts.append(el('li','',typeof part==='string'?part:(part.name||part.label||'Part')+' × '+(part.quantity||1)+(part.dimensions?' · '+part.dimensions.map(n=>Number(n).toFixed(1)).join(' × ')+' mm':'')));details.append(parts);}card.append(details);}list.append(card);}}

